









































import { Component, Vue } from 'vue-property-decorator'
import { deviceApi } from '@/api/interface'

import { emitter } from '@/utils/emmiter'

@Component({
  name: 'DeviceModal'
})
export default class DeviceModal extends Vue {
  private newPeerForm = {
    private_key: '',
    public_key: '',
    preshared_key: '',
    allowed_ips: '',
    persistent_keepalive_interval: '',
    endpoint: ''
  }

  public async createDevice(): Promise<void> {
    const newPeerData = JSON.parse(JSON.stringify(this.newPeerForm))

    Object.keys(newPeerData).forEach(key => {
      if (!newPeerData[key]) {
        delete newPeerData[key]
      }
    })

    const newPeer = {
      ...newPeerData,
      allowed_ips: Object.keys(newPeerData).includes('allowed_ips') ? newPeerData.allowed_ips.replace(/\s+/g, '').split(',').filter(Boolean) : null
    }

    await deviceApi.createDevicePeer(this.$route.params.id, newPeer)
    this.$emit('close')
    emitter.emit('updatePeer')
    this.$message({
      type: 'success',
      message: 'New peer create'
    })
  }
}
